using System.Collections.Generic;
using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "BattleActionToRandomEnemyOmenLogic", menuName = "Data/Battle/Omens System/Omen Logic/BattleActionToRandomEnemy Omen Logic")]
public class BattleActionToRandomEnemyOmenLogic : OmenLogic
{
	[Header("Units")]
	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[SerializeField]
	private bool directPurify;

	[SerializeField]
	private DirectPurifyCorruptEnum directPurifyCorruptEnum;

	public override void ActivateOmen(BattleAction battleAction, int actionValue, GameObject target, GameObject source, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum = CorruptionPurifyModifierEnum.NONE, bool playSFX = false)
	{
		GameObject gameObject = null;
		List<GameObject> list = currentCorruptedAnimals.activeCorruptedAnimals.Duplicate();
		list.RemoveAll((GameObject enemy) => enemy.GetComponent<CorruptedAnimalCorruptionStats>().IsDefeated());
		if (list.Count != 0)
		{
			gameObject = list.PickRandom();
			if (directPurifyCorruptEnum == DirectPurifyCorruptEnum.DirectPurify)
			{
				gameObject.GetComponent<CorruptionStats>().Purify(actionValue, source);
			}
			else if (directPurifyCorruptEnum == DirectPurifyCorruptEnum.DirectCorrupt)
			{
				gameObject.GetComponent<CorruptionStats>().Corrupt(actionValue, source, corruptionPurifyModifierEnum);
			}
			else
			{
				battleAction.CastTargetAmount(gameObject, actionValue, source);
			}
		}
	}
}
